import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, random } from '../remotionShim';
// --- Font Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Icons ---
const AirplaneIcon: React.FC<{ style?: React.CSSProperties }> = ({ style }) => (
  <svg
    viewBox="0 0 24 24"
    fill="currentColor"
    style={{ width: "100%", height: "100%", ...style }}
  >
    <path d="M21 16v-2l-8-5V3.5c0-.83-.67-1.5-1.5-1.5S10 2.67 10 3.5V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z" />
  </svg>
);

// --- Constants ---
const CHAR_SET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .:";
const DEFAULT_COLS = {
  TIME: 5,
  DEST: 10,
  FLIGHT: 7,
};

// --- Sub-components ---

// Single Split-Flap Character
const SplitFlapChar: React.FC<{
  char: string;
  delay: number;
  duration: number;
  width: number;
}> = ({ char, delay, duration, width }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // "Cycling" Logic
  // We want to cycle through random characters until we hit the 'delay + duration' frame.
  // After that, we show the final 'char'.
  
  const progress = interpolate(frame, [delay, delay + duration], [0, 1], {
    extrapolateRight: "clamp",
  });

  // Calculate which random character to show during the animation
  // We cycle through 20 chars per second of animation roughly
  const cycleSpeed = 20; 
  const cycleIndex = Math.floor(frame / (fps / cycleSpeed));
  
  // Deterministic random based on position and time so it doesn't flicker randomly every render
  const randomCharIndex = Math.floor(random(cycleIndex + delay) * CHAR_SET.length);
  const displayChar = progress >= 1 ? char : CHAR_SET[randomCharIndex];

  // Visual Styling for the "Split"
  const charStyle: React.CSSProperties = {
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    width: width,
    height: width * 1.5, // 2:3 Aspect ratio
    backgroundColor: "#111",
    color: "#eee",
    fontSize: width * 1,
    fontFamily: "Roboto Mono",
    fontWeight: 700,
    borderRadius: 4,
    position: "relative",
    overflow: "hidden",
    boxShadow: "0 2px 4px rgba(0,0,0,0.5)",
    margin: "0 2px", // Gap between chars
  };

  const lineStyle: React.CSSProperties = {
    position: "absolute",
    top: "50%",
    left: 0,
    right: 0,
    height: 1,
    backgroundColor: "rgba(0,0,0,0.8)",
    zIndex: 10,
  };

  const glossStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    height: "50%",
    background: "linear-gradient(to bottom, rgba(255,255,255,0.1), rgba(255,255,255,0.02))",
    borderBottom: "1px solid rgba(0,0,0,0.5)",
  };

  return (
    <div style={charStyle}>
      <span style={{ position: "relative", top: -width * 0.05 }}>{displayChar}</span>
      <div style={lineStyle} />
      <div style={glossStyle} />
    </div>
  );
};

// Row of Split-Flap Characters
const FlapRow: React.FC<{
  text: string;
  length: number;
  startDelay: number;
  charWidth: number;
}> = ({ text, length, startDelay, charWidth }) => {
  // Pad or truncate text to fit length
  const normalizedText = text.toUpperCase().padEnd(length, " ").slice(0, length);

  return (
    <div style={{ display: "flex", flexDirection: "row" }}>
      {normalizedText.split("").map((char, i) => (
        <SplitFlapChar
          key={i}
          char={char}
          delay={startDelay + i * 3} // Stagger effect
          duration={20} // ~0.7 seconds of shuffling per char
          width={charWidth}
        />
      ))}
    </div>
  );
};

// --- Schema ---


export type DeparturesBoardProps = Record<string, any>;

const DeparturesBoard: React.FC<DeparturesBoardProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  row1Time = "11:30",
  row1Dest = "BERLIN",
  row1Flight = "TU 4709",
  row2Time = "12:45",
  row2Dest = "KIEV",
  row2Flight = "UA 6385",
  row3Time = "14:10",
  row3Dest = "HONG KONG",
  row3Flight = "JP 8290",
}) => {
  
  useFontLoader(["Oswald", "Roboto Mono"]);
  
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive calculations
  const PADDING = width * 0.05;
  const CONTENT_WIDTH = width - PADDING * 2;
  const CHAR_WIDTH = CONTENT_WIDTH / 26; // Approx fit for the layout
  
  // Layout Constants
  const HEADER_HEIGHT = height * 0.25;
  const ROW_HEIGHT = height * 0.15;
  const LABEL_ROW_HEIGHT = height * 0.08;

  // Animation Timings
  const headerEntrance = spring({ frame, fps, config: { damping: 20 } });
  
  // Row Data
  const rows = [
    { time: row1Time, dest: row1Dest, flight: row1Flight, delay: 15 },
    { time: row2Time, dest: row2Dest, flight: row2Flight, delay: 35 },
    { time: row3Time, dest: row3Dest, flight: row3Flight, delay: 55 },
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Oswald", color: "white" }}>
      
      {/* --- Main Container --- */}
      <div style={{ 
        position: 'absolute', 
        top: PADDING, 
        left: PADDING, 
        width: CONTENT_WIDTH,
        height: height - PADDING * 2,
        display: 'flex',
        flexDirection: 'column'
      }}>

        {/* --- Header --- */}
        <div style={{
          height: HEADER_HEIGHT,
          backgroundColor: '#000',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          borderBottom: '4px solid #333',
          marginBottom: LABEL_ROW_HEIGHT * 0.5,
          opacity: headerEntrance,
          transform: `translateY(${interpolate(headerEntrance, [0, 1], [-50, 0])}px)`
        }}>
          {/* Left Icon */}
          <div style={{ width: HEADER_HEIGHT * 0.4, height: HEADER_HEIGHT * 0.4, marginLeft: 20 }}>
            <AirplaneIcon style={{ transform: "rotate(-45deg)" }} />
          </div>

          {/* Title */}
          <h1 style={{ 
            fontSize: HEADER_HEIGHT * 0.6, 
            margin: 0, 
            letterSpacing: 4, 
            textTransform: 'uppercase',
            fontWeight: 700 
          }}>
            Departures
          </h1>

          {/* Right Icon */}
          <div style={{ width: HEADER_HEIGHT * 0.4, height: HEADER_HEIGHT * 0.4, marginRight: 20 }}>
            <AirplaneIcon style={{ transform: "rotate(45deg)" }} />
          </div>
        </div>

        {/* --- Column Labels --- */}
        <div style={{
          display: 'flex',
          height: LABEL_ROW_HEIGHT,
          alignItems: 'center',
          fontSize: LABEL_ROW_HEIGHT * 0.6,
          fontWeight: 600,
          color: '#ccc',
          paddingBottom: 10
        }}>
          <div style={{ width: CHAR_WIDTH * DEFAULT_COLS.TIME * 1.5 }}>TIME</div>
          <div style={{ flex: 1, paddingLeft: 10 }}>DESTINATION</div>
          <div style={{ width: CHAR_WIDTH * DEFAULT_COLS.FLIGHT * 1.5 }}>FLIGHT</div>
        </div>

        {/* --- Rows --- */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 10 }}>
          {rows.map((row, index) => {
            // Row entrance animation (slide in)
            const rowEntrance = spring({
              frame: frame - row.delay * 0.5,
              fps,
              config: { damping: 15 }
            });
            const opacity = interpolate(rowEntrance, [0, 1], [0, 1], { extrapolateRight: "clamp" });
            const translateY = interpolate(rowEntrance, [0, 1], [20, 0], { extrapolateRight: "clamp" });

            return (
              <div
                key={index}
                style={{
                  height: ROW_HEIGHT,
                  display: 'flex',
                  alignItems: 'center',
                  opacity,
                  transform: `translateY(${translateY}px)`
                }}
              >
                {/* Time Column */}
                <div style={{ width: CHAR_WIDTH * DEFAULT_COLS.TIME * 1.5 }}>
                  <FlapRow 
                    text={row.time} 
                    length={DEFAULT_COLS.TIME} 
                    startDelay={row.delay} 
                    charWidth={CHAR_WIDTH} 
                  />
                </div>

                {/* Destination Column */}
                <div style={{ flex: 1, paddingLeft: 10 }}>
                  <FlapRow 
                    text={row.dest} 
                    length={DEFAULT_COLS.DEST} 
                    startDelay={row.delay + 10} // Slight delay after time
                    charWidth={CHAR_WIDTH} 
                  />
                </div>

                {/* Flight Column */}
                <div style={{ width: CHAR_WIDTH * DEFAULT_COLS.FLIGHT * 1.5 }}>
                  <FlapRow 
                    text={row.flight} 
                    length={DEFAULT_COLS.FLIGHT} 
                    startDelay={row.delay + 20} // Slight delay after dest
                    charWidth={CHAR_WIDTH} 
                  />
                </div>
              </div>
            );
          })}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default DeparturesBoard;